package com.meterflow.invoicing;
import com.meterflow.catalogue.*;import com.meterflow.metering.*;import com.meterflow.subscriptions.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service public class LateAdjustmentBillingService {private final LateUsageAdjustmentRepository ledger;private final UsageEventRepository events;private final SubscriptionRepository subs;private final PlanRepository plans;private final PricingService pricing;private final InvoiceAdjustmentRepository adjustments;
 public LateAdjustmentBillingService(LateUsageAdjustmentRepository l,UsageEventRepository e,SubscriptionRepository s,PlanRepository p,PricingService pr,InvoiceAdjustmentRepository a){ledger=l;events=e;subs=s;plans=p;pricing=pr;adjustments=a;}
 @Transactional public InvoiceAdjustment bill(String customer,String period){YearMonth ym=YearMonth.parse(period);var pending=ledger.findByCustomerIdAndBillingPeriodAndStatus(customer,period,"PENDING");if(pending.isEmpty())throw new IllegalArgumentException("No pending late usage adjustments");var sub=subs.findTopByCustomerIdAndStatusOrderByPeriodStartDesc(customer,"ACTIVE").orElseThrow();var plan=plans.findById(sub.getPlanId()).orElseThrow();var lateIds=pending.stream().map(LateUsageAdjustment::getUsageEventId).toList();var lateEvents=java.util.stream.StreamSupport.stream(events.findAllById(lateIds).spliterator(),false).toList();if(lateEvents.stream().anyMatch(e->!e.getMetric().equals(plan.getMetric())))throw new IllegalStateException("Pending late events include metrics not billable on the current plan; resolve plan history before adjustment");BigDecimal adjustment=BigDecimal.ZERO;for(String metric:lateEvents.stream().map(UsageEvent::getMetric).distinct().toList()){var late=lateEvents.stream().filter(e->e.getMetric().equals(metric)).map(UsageEvent::getQuantity).reduce(BigDecimal.ZERO,BigDecimal::add);if(!metric.equals(plan.getMetric()))continue;Instant from=ym.atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();Instant to=ym.plusMonths(1).atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();var all=events.findMetricWindow(customer,metric,from,to).stream().map(UsageEvent::getQuantity).reduce(BigDecimal.ZERO,BigDecimal::add);var base=all.subtract(late).max(BigDecimal.ZERO);adjustment=adjustment.add(pricing.calculate(plan,all,BigDecimal.valueOf(sub.getSeatCount())).subtract(pricing.calculate(plan,base,BigDecimal.valueOf(sub.getSeatCount()))).max(BigDecimal.ZERO));}if(adjustment.signum()==0)throw new IllegalStateException("Late events did not change the billable amount");BigDecimal tax=adjustment.multiply(plan.getTaxRate()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);var saved=adjustments.save(new InvoiceAdjustment(customer,period,plan.getCurrency(),adjustment,tax,"Late usage received within 72-hour post-close grace period; event count="+lateEvents.size()));pending.forEach(LateUsageAdjustment::markInvoiced);ledger.saveAll(pending);return saved;}
}
